# Cache Package Examples

## Example 1: Basic Cache Operations (Thread-Safe)

```go
package main

import (
	"fmt"
	"time"
	"yourmodule/cache"
)

func main() {
	// Create a thread-safe cache with 5-minute TTL
	c := cache.New(5 * time.Minute)

	// Set values
	c.Set("user:1", "Alice")
	c.Set("user:2", "Bob")
	c.Set("count", 42)

	// Get values (thread-safe read)
	if val, exists := c.Get("user:1"); exists {
		fmt.Println("Found:", val) // Output: Found: Alice
	}

	// Delete entry (thread-safe write)
	c.Delete("user:2")

	// Get after delete
	if _, exists := c.Get("user:2"); !exists {
		fmt.Println("user:2 not found after deletion")
	}

	// Purge all (thread-safe write)
	c.Purge()
	fmt.Println("Cache cleared")
}
```

