```go
package main

import (
	"fmt"
	"sync"
	"time"
	"yourmodule/cache"
)

func main() {
	c := cache.New(10 * time.Second)
	c.Set("product:101", "Laptop")
	c.Set("product:102", "Mouse")

	var wg sync.WaitGroup

	// 5 goroutines reading concurrently (safe: read-locked)
	for i := 1; i <= 5; i++ {
		wg.Add(1)
		go func(goroutineID int) {
			defer wg.Done()
			if val, exists := c.Get("product:101"); exists {
				fmt.Printf("Goroutine %d: Read %v\n", goroutineID, val)
			}
		}(i)
	}

	wg.Wait()
	fmt.Println("All concurrent reads completed safely")
}
