package main

import (
	"fmt"
	"sync"
	"time"
	"yourmodule/cache"
)

func main() {
	c := cache.New(10 * time.Second)
	var wg sync.WaitGroup

	// 3 goroutines writing concurrently (safe: write-locked)
	for i := 1; i <= 3; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			c.Set(fmt.Sprintf("session:%d", id), fmt.Sprintf("token_%d", id))
			fmt.Printf("Wrote session:%d\n", id)
		}(i)
	}

	wg.Wait()

	// Verify all writes (thread-safe read)
	for i := 1; i <= 3; i++ {
		if val, ok := c.Get(fmt.Sprintf("session:%d", i)); ok {
			fmt.Printf("Verified: %v\n", val)
		}
	}
}
