## Example 4: Mixed Concurrent Operations (Thread-Safe)

```go
package main

import (
	"fmt"
	"sync"
	"time"
	"yourmodule/cache"
)

func main() {
	c := cache.New(10 * time.Second)
	var wg sync.WaitGroup

	// Writer goroutine
	wg.Add(1)
	go func() {
		defer wg.Done()
		for i := 0; i < 5; i++ {
			c.Set(fmt.Sprintf("key:%d", i), fmt.Sprintf("value_%d", i))
			time.Sleep(100 * time.Millisecond)
		}
		fmt.Println("Writer: Finished")
	}()

	// Reader goroutines
	for i := 0; i < 3; i++ {
		wg.Add(1)
		go func(readerID int) {
			defer wg.Done()
			for j := 0; j < 5; j++ {
				if val, exists := c.Get(fmt.Sprintf("key:%d", j)); exists {
					fmt.Printf("Reader %d: Found %v\n", readerID, val)
				}
				time.Sleep(50 * time.Millisecond)
			}
		}(i)
	}

	// Cleanup goroutine
	wg.Add(1)
	go func() {
		defer wg.Done()
		time.Sleep(200 * time.Millisecond)
		c.Delete("key:2")
		fmt.Println("Cleanup: Deleted key:2")
	}()

	wg.Wait()
	fmt.Println("All operations completed safely")
}
