## Example 1: Basic Cache Operations

**Documentation:** Simple get, set, and delete operations.

```go
package main

import (
    "fmt"
    "time"
    "your-module/cache"
)

func main() {
    // Create a cache with 5-minute TTL
    c := cache.New(5 * time.Minute)

    // Set simple string value
    c.Set("greeting", "Hello, World!")

    // Set integer value
    c.Set("counter", 42)

    // Set complex struct
    type User struct {
        ID    int
        Name  string
        Email string
    }

    c.Set("user:123", User{
        ID:    123,
        Name:  "Alice Johnson",
        Email: "alice@example.com",
    })

    // Retrieve values safely
    if greeting, found := c.Get("greeting"); found {
        fmt.Printf("Greeting: %v\n", greeting) // Greeting: Hello, World!
    }

    if counter, found := c.Get("counter"); found {
        fmt.Printf("Counter: %v\n", counter) // Counter: 42
    }

    if user, found := c.Get("user:123"); found {
        u := user.(User) // Type assertion
        fmt.Printf("User: %s <%s>\n", u.Name, u.Email)
        // User: Alice Johnson <alice@example.com>
    }

    // Delete specific key
    c.Delete("greeting")
    if _, found := c.Get("greeting"); !found {
        fmt.Println("Greeting has been deleted")
    }
}
