## Example 5: API Response Caching

**Documentation:** Caching HTTP API responses with automatic expiration.

```go
package main

import (
    "fmt"
    "time"
    "your-module/cache"
)

type APIResponse struct {
    StatusCode int
    Data       interface{}
    FetchedAt  time.Time
}

type CachedAPIClient struct {
    cache *cache.Cache
}

func NewCachedAPIClient(cacheTTL time.Duration) *CachedAPIClient {
    return &CachedAPIClient{
        cache: cache.New(cacheTTL),
    }
}

// Simulated API call
func (c *CachedAPIClient) fetchUserData(userID int) APIResponse {
    fmt.Printf("  [API Call] Fetching user data for ID: %d\n", userID)
    // In real code, this would make an HTTP request
    return APIResponse{
        StatusCode: 200,
        Data: map[string]interface{}{
            "id":   userID,
            "name": fmt.Sprintf("User %d", userID),
        },
        FetchedAt: time.Now(),
    }
}

// GetUserData with caching
func (c *CachedAPIClient) GetUserData(userID int) APIResponse {
    cacheKey := fmt.Sprintf("user:%d", userID)

    // Check cache first
    if cached, found := c.cache.Get(cacheKey); found {
        response := cached.(APIResponse)
        fmt.Printf("✓ Cache hit for user %d (fetched %v ago)\n",
            userID, time.Since(response.FetchedAt).Round(time.Second))
        return response
    }

    // Cache miss - fetch from API
    fmt.Printf("✗ Cache miss for user %d\n", userID)
    response := c.fetchUserData(userID)
    c.cache.Set(cacheKey, response)
    return response
}

func main() {
    fmt.Println("=== API Response Caching Example ===\n")

    // Create client with 5-second cache TTL
    client := NewCachedAPIClient(5 * time.Second)

    // First request (cache miss)
    fmt.Println("First request for user 1:")
    client.GetUserData(1)

    fmt.Println()

    // Second request (cache hit)
    fmt.Println("Second request for user 1 (within TTL):")
    client.GetUserData(1)

    fmt.Println()

    // Wait for cache to expire
    fmt.Println("Waiting 6 seconds for cache to expire...")
    time.Sleep(6 * time.Second)

    fmt.Println()

    // Request after expiration (cache miss)
    fmt.Println("Third request for user 1 (after TTL):")
    client.GetUserData(1)
}
```

