## Example 6: Cleanup and Maintenance

**Documentation:** Managing cache cleanup and memory efficiency.

```go
package main

import (
    "fmt"
    "time"
    "your-module/cache"
)

func main() {
    fmt.Println("=== Cache Cleanup and Maintenance ===\n")

    c := cache.New(2 * time.Second)

    // Populate cache
    fmt.Println("Adding 5 items to cache...")
    for i := 1; i <= 5; i++ {
        key := fmt.Sprintf("item:%d", i)
        c.Set(key, fmt.Sprintf("value_%d", i))
    }
    fmt.Println("✓ 5 items stored")

    fmt.Println()

    // Example 1: Delete specific items
    fmt.Println("Deleting specific items...")
    c.Delete("item:1")
    c.Delete("item:2")
    fmt.Println("✓ Deleted item:1 and item:2")

    // Verify deletions
    fmt.Println("\nChecking remaining items:")
    for i := 1; i <= 5; i++ {
        key := fmt.Sprintf("item:%d", i)
        if _, found := c.Get(key); found {
            fmt.Printf("  ✓ %s exists\n", key)
        } else {
            fmt.Printf("  ✗ %s not found\n", key)
        }
    }

    fmt.Println()

    // Example 2: Purge entire cache
    fmt.Println("Purging entire cache...")
    c.Purge()
    fmt.Println("✓ All items cleared")

    // Verify purge
    if _, found := c.Get("item:3"); !found {
        fmt.Println("✓ Cache is empty")
    }

    fmt.Println()

    // Example 3: Automatic expiration
    fmt.Println("Testing automatic TTL expiration...")
    c2 := cache.New(1 * time.Second)
    c2.Set("temporary", "data")
    fmt.Println("✓ Item stored with 1-second TTL")

    fmt.Println("Checking after 0.5 seconds...")
    time.Sleep(500 * time.Millisecond)
    if _, found := c2.Get("temporary"); found {
        fmt.Println("✓ Item still exists")
    }

    fmt.Println("Checking after 1.5 seconds total...")
    time.Sleep(1000 * time.Millisecond)
    if _, found := c2.Get("temporary"); !found {
        fmt.Println("✓ Item automatically expired")
    }
}
