    sessionCache.Set("session:user:456", "token_abc123xyz")
    fmt.Println("Session stored")

    // Immediately retrieve (should succeed)
    if token, found := sessionCache.Get("session:user:456"); found {
        fmt.Printf("✓ Token found: %v\n", token)
    }

    // Wait for TTL to expire
    fmt.Println("Waiting 3 seconds for TTL expiration...")
    time.Sleep(3 * time.Second)

    // Attempt retrieval after expiration (should fail)
    if _, found := sessionCache.Get("session:user:456"); !found {
        fmt.Println("✗ Token expired (as expected)")
    }

    // Practical example: Using different TTLs for different data types
    fmt.Println("\n=== Different TTLs for Different Data ===")

    // Fast-changing data: short TTL
    apiResponseCache := cache.New(30 * time.Second)
    apiResponseCache.Set("api:weather", "Sunny, 72°F")

    // Stable data: long TTL
    configCache := cache.New(24 * time.Hour)
    configCache.Set("config:database_url", "postgres://localhost/mydb")

    fmt.Println("API cache TTL: 30 seconds (frequently updated data)")
    fmt.Println("Config cache TTL: 24 hours (stable data)")
}
