### Example 3: Concurrent Access (Thread-Safe)

Multiple goroutines safely reading and writing to the cache simultaneously.

```go
package main

import (
    "fmt"
    "sync"
    "time"
    "your-module/cache"
)

func main() {
    c := cache.New(10 * time.Minute)
    var wg sync.WaitGroup

    fmt.Println("=== Thread-Safe Concurrent Access ===\n")

    numWorkers := 5
    numOpsPerWorker := 100

    // Start writer goroutines
    for workerID := 0; workerID < numWorkers; workerID++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            for i := 0; i < numOpsPerWorker; i++ {
                key := fmt.Sprintf("worker:%d:item:%d", id, i)
                value := i * 10
                c.Set(key, value)
            }
        }(workerID)
    }

    // Start reader goroutines
    for workerID := 0; workerID < numWorkers; workerID++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            successCount := 0
            for i := 0; i < numOpsPerWorker; i++ {
                key := fmt.Sprintf("worker:%d:item:%d", id, i)
                if _, found := c.Get(key); found {
                    successCount++
                }
            }
            fmt.Printf("Worker %d: Read %d/%d items\n", id, successCount, numOpsPerWorker)
        }(workerID)
    }

    // Start delete goroutines (aggressive cache mutation)
    for workerID := 0; workerID < numWorkers; workerID++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            deleteCount := 0
            for i := 0; i < numOpsPerWorker/10; i++ {
                key := fmt.Sprintf("worker:%d:item:%d", id, i)
                c.Delete(key)
                deleteCount++
            }
            fmt.Printf("Worker %d: Deleted %d items\n", id, deleteCount)
        }(workerID)
    }

    // Wait for all goroutines to complete
    wg.Wait()
    fmt.Println("\n✓ All concurrent operations completed without data races")
}
```

