### Example 4: Real-World Scenario - User Session Cache

Practical caching pattern for managing user sessions in a web application.

```go
package main

import (
    "fmt"
    "sync"
    "time"
    "your-module/cache"
)

type Session struct {
    UserID    int
    Username  string
    Token     string
    LoginTime time.Time
    LastSeen  time.Time
}

type SessionManager struct {
    cache *cache.Cache
    mu    sync.RWMutex
}

func NewSessionManager(ttl time.Duration) *SessionManager {
    return &SessionManager{
        cache: cache.New(ttl),
    }
}

func (sm *SessionManager) CreateSession(userID int, username string) string {
    sessionID := fmt.Sprintf("session:%d:%d", userID, time.Now().UnixNano())

    session := Session{
        UserID:    userID,
        Username:  username,
        Token:     sessionID,
        LoginTime: time.Now(),
        LastSeen:  time.Now(),
    }

    sm.cache.Set(sessionID, session)
    return sessionID
}

func (sm *SessionManager) GetSession(sessionID string) (Session, bool) {
    val, found := sm.cache.Get(sessionID)
    if !found {
        return Session{}, false
    }

    session := val.(Session)
    return session, true
}

func (sm *SessionManager) UpdateLastSeen(sessionID string) bool {
    val, found := sm.cache.Get(sessionID)
    if !found {
        return false
    }

    session := val.(Session)
    session.LastSeen = time.Now()
    sm.cache.Set(sessionID, session)
    return true
}

func (sm *SessionManager) InvalidateSession(sessionID string) {
    sm.cache.Delete(sessionID)
}

func (sm *SessionManager) InvalidateAllSessions() {
    sm.cache.Purge()
}

// Usage
func main() {
    fmt.Println("=== Session Manager Example ===\n")

    sm := NewSessionManager(15 * time.Minute)

    // Create sessions for multiple users
    sessionIDs := make([]string, 3)
    for i := 1; i <= 3; i++ {
        sessionID := sm.CreateSession(i, fmt.Sprintf("user%d", i))
        sessionIDs[i-1] = sessionID
        fmt.Printf("Created session for user%d: %s\n", i, sessionID)
    }

    fmt.Println()

    // Simulate user activity
    for _, sessionID := range sessionIDs {
        if session, found := sm.GetSession(sessionID); found {
            fmt.Printf("Active session: %s (logged in at %v)\n",
                session.Username, session.LoginTime.Format("15:04:05"))
        }
    }

    fmt.Println()

    // Update last seen timestamp
    sm.UpdateLastSeen(sessionIDs[0])
    fmt.Println("Updated last seen for user1")

    // Invalidate specific session (logout)
    sm.InvalidateSession(sessionIDs[1])
    fmt.Println("Invalidated session for user2")

    if _, found := sm.GetSession(sessionIDs[1]); !found {
        fmt.Println("✓ User2 session no longer exists")
    }

    // Invalidate all sessions (global logout)
    sm.InvalidateAllSessions()
    fmt.Println("\nGlobal logout: All sessions cleared")
}
