# Refactored handleRequest - Pipeline Composition

```go
package user

// Pipeline orchestrates the request processing workflow
type Pipeline struct {
	validator  Validator
	normalizer Normalizer
	repository UserRepository
	notifier   Notifier
}

// NewPipeline creates a configured pipeline with all dependencies
func NewPipeline(
	validator Validator,
	normalizer Normalizer,
	repository UserRepository,
	notifier Notifier,
) *Pipeline {
	return &Pipeline{
		validator:  validator,
		normalizer: normalizer,
		repository: repository,
		notifier:   notifier,
	}
}

// HandleRequest executes the composed pipeline
func (p *Pipeline) HandleRequest(req Request) (*User, error) {
	if err := p.validator.Validate(req); err != nil {
		return nil, err
	}

	req = p.normalizer.Normalize(req)

	user, err := p.repository.FindOrCreate(req.Name, req.Email)
	if err != nil {
		return nil, err
	}

	if user == nil {
		user = &User{Name: req.Name, Email: req.Email, Age: req.Age}
		if err := p.repository.Save(user); err != nil {
			return nil, err
		}
	}

	if err := p.notifier.Notify(user); err != nil {
		return nil, err
	}

	return user, nil
}
```

