// PropertyBasedTests validates invariant properties for random inputs
func TestMergeSortProperties(t *testing.T) {
	testCases := [][]int{
		{},                           // empty
		{1},                          // single element
		{2, 1},                       // two elements
		{3, 1, 4, 1, 5, 9, 2, 6},   // basic
		{1, 1, 1, 1},                // all duplicates
		{5, 4, 3, 2, 1},             // reverse sorted
		{-10, -5, 0, 5, 10},         // negative numbers
		{1000000, 1, 999999, -1},    // large range
	}

	for idx, input := range testCases {
		t.Run("property_test_"+string(rune(idx)), func(t *testing.T) {
			result := make([]int, len(input))
			copy(result, input)

			MergeSort(result)

			// PROPERTY 1: Sorted Output - all adjacent elements are in order
			for i := 0; i < len(result)-1; i++ {
				if result[i] > result[i+1] {
					t.Fatalf("Property violated: Output not sorted at index %d. Got %v", i, result)
				}
			}

			// PROPERTY 2: Same Length - output length equals input length
			if len(result) != len(input) {
				t.Fatalf("Property violated: Length changed. Input: %d, Output: %d",
					len(input), len(result))
			}

			// PROPERTY 3: Same Elements - multiset equality (count preservation)
			counts := make(map[int]int)
			for _, v := range input {
				counts[v]++
			}
			for _, v := range result {
				counts[v]--
			}
			for v, count := range counts {
				if count != 0 {
					t.Fatalf("Property violated: Element count mismatch for %d. Net delta: %d. Input: %v, Output: %v",
						v, count, input, result)
				}
			}

			// PROPERTY 4: Idempotence - sorting twice yields same result
			result2 := make([]int, len(result))
			copy(result2, result)
			MergeSort(result2)
			if !slices.Equal(result, result2) {
				t.Fatalf("Property violated: Sorting is not idempotent. First: %v, Second: %v",
					result, result2)
			}
		})
	}
}

